158	    /**
159	     * Getter method for the maximum age of the organism.
160	     *
161	     * @return An integer value representing the maximum age.
162	     */
163	    abstract public int getMaxAge();
164	
165	    /**
166	     * Getter method for the age of breeding of the organism.
167	     *
168	     * @return A double value representing the breeding age.
169	     */
170	    abstract public int getBreedingAge();
171	
172	    /**
173	     * Called when breeding occurs for this organism.
174	     *
175	     * @return The number of births as a result of breeding.
176	     */
177	    protected int breed() {
178	        int births = 0;
179	        if(canBreed() && rand.nextDouble() <= getBreedingProbability()) {
180	            births = rand.nextInt(getMaxLitterSize()) + 1;
181	        }
182	        return births;
183	    }
184	
185	    /**
186	     * Create a new instance of this organism.
187	     * @param field The field in which the spawn will reside in.
188	     * @param location The location in which the spawn will occupy.
189	     * @return A new Organism instance.
190	     */
191	    abstract protected Organism createNewOrganism(Field field, Location location);
192	
193	    /**
194	     * Check whether or not this organism is to give birth at this step.
195	     * New births will be made into free adjacent locations.
196	     * @param newOrganisms A list to return newly born organisms.
197	     */
198	    protected void giveBirth(List<Organism> newOrganisms) {
199	        // New organisms are born into adjacent locations.
200	        // Get a list of adjacent free locations.
201	        Field field = getField();
202	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
203	        int births = breed();
204	        for(int b = 0; b < births && free.size() > 0; b++) {
205	            Location loc = free.remove(0);
206	            newOrganisms.add(createNewOrganism(field, loc));
207	        }
208	    }
209	
210	    /**
211	     * Checks all adjacent location for organisms that meet specific
212	     * breeding conditions, and returns true if it is even possible.
213	     *
214	     * @return Whether this organism can breed or not.
215	     */
216	    abstract protected boolean canBreed();
217	
218	    /**
219	     * Increase the age.
220	     * This could result in the organisms death.
221	     */
222	    protected void incrementAge()
223	    {
224	        age++;
225	
226	        if (age > getMaxAge()) {
227	            //setDead();
228	            remove();
229	        }
230	    }
231	
232	    /**
233	     * Getter method for the current age of this organism.
234	     *
235	     * @return An integer value representing age.
236	     */
237	    protected int getAge() {
238	        return this.age;
239	    }
240	
241	    /**
242	     * Setter method for the field in which this organism resides.
243	     * @param field The field where the organism is located.
244	     */
245	    protected void setField(Field field) {
246	        this.field = field;
247	    }
248	
249	    /**
250	     * Prevents overcrowding of dead animals
251	     * Remove the organism from the field after being dead for a s
252	     * specified number of steps and not being eaten.
253	     */
254	    protected void decayifDead() {
255	        this.howLongDead++;
256	        if (this.howLongDead > LIFETIME_AFTER_DEATH){
257	            remove();
258	        }
259	    }
260	}

