 25	    public Prey(int foodValue, boolean randomAge, Field field, Location location) {
 26	        super(randomAge, field, location);
 27	
 28	        this.foodValue = foodValue;
 29	        this.activeness = DEFAULT_ACTIVENESS;
 30	    }
 31	
 32	    /**
 33	     * Method for what the prey does, i.e. what is always run at every step.
 34	     *
 35	     * @param newPrey A list of all newborn prey in this simulation step.
 36	     * @param weather The current state of weather in the simulation.
 37	     * @param time The current state of time in the simulation.
 38	     */
 39	    @Override
