 59	    /**
 60	     * Increment the food value of this prey by a specified amount.
 61	     * @param foodValue The given amount to increase the food value by.
 62	     */
 63	    protected void incrementFoodValue(int foodValue) {
 64	        this.foodValue += foodValue;
 65	    }
 66	
 67	    /**
 68	     * Called when this prey eats a plant.
 69	     *
 70	     * @param consumable The plant to be eaten.
 71	     * @return Whether the plant was eaten.
 72	     */
 73	    @Override
 74	    public boolean eat(Consumable consumable) {
 75	        if ((consumable.isPoisonous()) && (!isInfected())) {
 76	            infect(this);
 77	        }
 78	        incrementFoodValue(consumable.getFoodValue());
 79	        consumable.setEaten();
 80	        return true;
 81	    }
 82	
 83	    /**
 84	     * Prey can never be poisonous.
 85	     * @return false as prey don't have this attribute.
 86	     */
 87	    @Override
 88	    public boolean isPoisonous() {
 89	        return false;
 90	    }
 91	
 92	    /**
 93	     * The activeness of this prey.
 94	     * @return A double value for the activeness of this prey
 95	     */
 96	    public double getActiveness() {
 97	        return activeness;
 98	    }
 99	
100	    /**
101	     * Setter method for the activeness of this prey.
102	     *
103	     * @param activeness A given value for activeness.
104	     */
105	    public void setActiveness(double activeness) {
106	        this.activeness = activeness;
107	    }
108	
109	    /**
110	     * Find a nearby plant and consume it if possible.
111	     *
112	     * @return The location of the food source, or null if none was eaten.
113	     */
114	    protected Location findPlantFood() {
115	        Field field = getField();
116	        for (Location where : field.adjacentLocations(getLocation())) {
117	            Organism organism = field.getOrganismAt(where);
118	            if (organism instanceof Plant) {
119	                Plant plant = (Plant) organism;
120	                if (plant.isAlive()) {
121	                    plant.setDead();
122	                    return eat(plant) ? where : null;
123	                }
124	            }
125	        }
126	        return null;
127	    }
128	}

