 30	        // randomly assign male or female
 31	        this.gender = Gender.getRandom();
 32	        this.infected = false;
 33	    }
 34	
 35	    /**
 36	     * Abstract method for what the animal does, i.e. what is always run at every step.
 37	     *
 38	     * @param newAnimals A list of all newborn animals in this simulation step.
 39	     * @param weather The current state of weather in the simulation.
 40	     * @param time The current state of time in the simulation.
 41	     */
 42	    @Override
