 54	    /**
 55	     * Checks all adjacent location for animals that meet specific
 56	     * breeding conditions, and returns true if it is even possible.
 57	     *
 58	     * @return Whether this animal can breed or not.
 59	     */
 60	    @Override
 61	    protected boolean canBreed() {
 62	        if (getAge() < getBreedingAge() || getField() == null || getLocation() == null) {
 63	            return false;
 64	        }
 65	
 66	        for (Location loc : getField().adjacentLocations(getLocation())) {
 67	            Organism organism = getField().getOrganismAt(loc);
 68	            if (organism != null && organism.getClass() == getClass()) {
 69	                Animal animal = (Animal) organism;
 70	                if (animal.isMale() != isMale()) {
 71	                    return true;
 72	                }
 73	            }
 74	        }
 75	        return false;
 76	    }
