  6	/**
  7	 * Represent a rectangular grid of field positions.
  8	 * Each position is able to store a single organism.
  9	 *
 10	 * @version 2016.02.29
 11	 */
 12	public class Field
 13	{
 14	    // A random number generator for providing random locations.
 15	    private static final Random rand = Randomizer.getRandom();
 16	    
 17	    // The depth and width of the field.
 18	    private int depth, width;
 19	    // Storage for the organisms.
 20	    private Organism[][] field;
 21	
 22	    /**
 23	     * Represent a field of the given dimensions.
 24	     * @param depth The depth of the field.
 25	     * @param width The width of the field.
 26	     */
 27	    public Field(int depth, int width)
 28	    {
 29	        this.depth = depth;
 30	        this.width = width;
 31	        field = new Organism[depth][width];
 32	    }
 33	    
 34	    /**
 35	     * Empty the field.
 36	     */
 37	    public void clear()
 38	    {
 39	        for(int row = 0; row < depth; row++) {
 40	            for(int col = 0; col < width; col++) {
 41	                field[row][col] = null;
 42	            }
 43	        }
 44	    }
 45	    
 46	    /**
 47	     * Clear the given location.
 48	     * @param location The location to clear.
 49	     */
 50	    public void clear(Location location)
 51	    {
 52	        field[location.getRow()][location.getCol()] = null;
 53	    }
 54	    
 55	    /**
 56	     * Place an animal at the given location.
 57	     * If there is already an animal at the location it will
 58	     * be lost.
 59	     * @param organism The organism to be placed.
 60	     * @param row Row coordinate of the location.
 61	     * @param col Column coordinate of the location.
 62	     */
 63	    public void place(Organism organism, int row, int col)
 64	    {
 65	        place(organism, new Location(row, col));
 66	    }
 67	    
 68	    /**
 69	     * Place an animal at the given location.
 70	     * If there is already an animal at the location it will
 71	     * be lost.
 72	     * @param organism The organism to be placed.
 73	     * @param location Where to place the animal.
 74	     */
 75	    public void place(Organism organism, Location location)
 76	    {
 77	        field[location.getRow()][location.getCol()] = organism;
 78	    }
 79	    
 80	    /**
 81	     * Return the organism at the given location, if any.
 82	     * @param location Where in the field.
 83	     * @return The organism at the given location, or null if there is none.
 84	     */
 85	    public Organism getOrganismAt(Location location)
 86	    {
 87	        return getOrganismAt(location.getRow(), location.getCol());
 88	    }
 89	    
 90	    /**
 91	     * Return the organism at the given location, if any.
 92	     * @param row The desired row.
 93	     * @param col The desired column.
 94	     * @return The organism at the given location, or null if there is none.
 95	     */
 96	    public Organism getOrganismAt(int row, int col)
 97	    {
 98	        return field[row][col];
 99	    }
100	    
101	    /**
102	     * Generate a random location that is adjacent to the
103	     * given location, or is the same location.
104	     * The returned location will be within the valid bounds
105	     * of the field.
106	     * @param location The location from which to generate an adjacency.
107	     * @return A valid location within the grid area.
108	     */
109	    public Location randomAdjacentLocation(Location location)
110	    {
111	        List<Location> adjacent = adjacentLocations(location);
112	        return adjacent.get(0);
113	    }
114	    
115	    /**
116	     * Get a shuffled list of the free adjacent locations.
117	     * @param location Get locations adjacent to this.
118	     * @return A list of free adjacent locations.
119	     */
120	    public List<Location> getFreeAdjacentLocations(Location location)
121	    {
122	        List<Location> free = new LinkedList<>();
123	        List<Location> adjacent = adjacentLocations(location);
124	        for(Location next : adjacent) {
125	            if(getOrganismAt(next) == null) {
126	                free.add(next);
127	            }
128	        }
129	        return free;
130	    }
131	    
132	    /**
133	     * Try to find a free location that is adjacent to the
134	     * given location. If there is none, return null.
135	     * The returned location will be within the valid bounds
136	     * of the field.
137	     * @param location The location from which to generate an adjacency.
138	     * @return A valid location within the grid area.
139	     */
140	    public Location freeAdjacentLocation(Location location)
141	    {
142	        // The available free ones.
143	        List<Location> free = getFreeAdjacentLocations(location);
144	        if(free.size() > 0) {
145	            return free.get(0);
146	        }
147	        else {
148	            return null;
149	        }
150	    }
151	
152	    /**
153	     * Return a shuffled list of locations adjacent to the given one.
154	     * The list will not include the location itself.
155	     * All locations will lie within the grid.
156	     * @param location The location from which to generate adjacencies.
157	     * @return A list of locations adjacent to that given.
158	     */
159	    public List<Location> adjacentLocations(Location location)
160	    {
161	        assert location != null : "Null location passed to adjacentLocations";
162	        // The list of locations to be returned.
163	        List<Location> locations = new LinkedList<>();
164	        if(location != null) {
165	            int row = location.getRow();
166	            int col = location.getCol();
167	            for(int roffset = -1; roffset <= 1; roffset++) {
168	                int nextRow = row + roffset;
169	                if(nextRow >= 0 && nextRow < depth) {
170	                    for(int coffset = -1; coffset <= 1; coffset++) {
171	                        int nextCol = col + coffset;
172	                        // Exclude invalid locations and the original location.
173	                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
174	                            locations.add(new Location(nextRow, nextCol));
175	                        }
176	                    }
177	                }
178	            }
179	            
180	            // Shuffle the list. Several other methods rely on the list
181	            // being in a random order.
182	            Collections.shuffle(locations, rand);
183	        }
184	        return locations;
185	    }
186	
187	    /**
188	     * Return the depth of the field.
189	     * @return The depth of the field.
190	     */
191	    public int getDepth()
192	    {
193	        return depth;
194	    }
195	    
196	    /**
197	     * Return the width of the field.
198	     * @return The width of the field.
199	     */
200	    public int getWidth()
201	    {
202	        return width;
203	    }
204	}

