 93	    /**
 94	     * @return The color to be used for a given class of animal.
 95	     */
 96	    private Color getColor(Class<? extends Organism> animalClass)
 97	    {
 98	        Color col = colors.get(animalClass);
 99	        if(col == null) {
100	            // no color defined for this class
101	            return UNKNOWN_COLOR;
102	        }
103	        else {
104	            return col;
105	        }
106	    }
