108	    /**
109	     * Show the current status of the field.
110	     * @param step Which iteration step it is.
111	     * @param field The field whose status is to be displayed.
112	     */
113	    public void showStatus(int step, Field field)
114	    {
115	        if(!isVisible()) {
116	            setVisible(true);
117	        }
118	        stepLabel.setText(STEP_PREFIX + step);
119	        stats.reset();
120	        
121	        fieldView.preparePaint();
122	
123	        for(int row = 0; row < field.getDepth(); row++) {
124	            for(int col = 0; col < field.getWidth(); col++) {
125	                Organism organism = field.getOrganismAt(row, col);
126	                if(organism != null) {
127	                    stats.incrementCount(organism.getClass());
128	                    fieldView.drawMark(col, row, getColor(organism.getClass()));
129	                }
130	                else {
131	                    fieldView.drawMark(col, row, EMPTY_COLOR);
132	                }
133	            }
134	        }
135	        stats.countFinished();
136	
137	        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field));
138	        fieldView.repaint();
139	    }
